package solution

import (
	"errors"
	"strings"
)

var ErrInvalidLevel = errors.New("invalid log level")

type Severity int

const (
	Debug Severity = iota
	Info
	Warn
	Error
	Fatal
)

type LogEntry struct {
	Level   Severity
	Message string
}

func asciiLower(value string) string {
	bytes := []byte(value)
	for index, character := range bytes {
		if character >= 'A' && character <= 'Z' {
			bytes[index] = character + ('a' - 'A')
		}
	}
	return string(bytes)
}

func ParseSeverity(value string) (Severity, error) {
	switch asciiLower(strings.TrimSpace(value)) {
	case "debug":
		return Debug, nil
	case "info":
		return Info, nil
	case "warn":
		return Warn, nil
	case "error":
		return Error, nil
	case "fatal":
		return Fatal, nil
	default:
		return Debug, ErrInvalidLevel
	}
}

func FilterLogs(minimum string, entries []LogEntry) ([]LogEntry, error) {
	level, err := ParseSeverity(minimum)
	if err != nil {
		return nil, ErrInvalidLevel
	}
	for _, entry := range entries {
		if entry.Level < Debug || entry.Level > Fatal {
			return nil, ErrInvalidLevel
		}
	}
	result := make([]LogEntry, 0)
	for _, entry := range entries {
		if entry.Level >= level {
			result = append(result, entry)
		}
	}
	return result, nil
}
